{
  "$schema": "https://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "replace_default_agents": {
      "type": "boolean",
      "default": true,
      "description": "If true, replaces OpenCode's default agents (plan, build) with only cline-plan and cline-act. If false, adds Cline agents alongside default agents."
    },
    "default_agent": {
      "type": "string",
      "enum": ["cline-plan", "cline-act"],
      "default": "cline-plan",
      "description": "Which agent to use by default when starting OpenCode"
    },
    "plan_model": {
      "type": "string",
      "description": "Model to use for cline-plan agent. If not specified, uses the default model from opencode.json"
    },
    "act_model": {
      "type": "string",
      "description": "Model to use for cline-act agent. If not specified, uses the default model from opencode.json"
    },
    "plan_temperature": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "default": 0.1,
      "description": "Temperature for plan mode (lower = more focused)"
    },
    "act_temperature": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "default": 0.3,
      "description": "Temperature for act mode"
    },
    "show_completion_toast": {
      "type": "boolean",
      "default": true,
      "description": "Show toast notification when plan is complete"
    },
    "enable_execute_command": {
      "type": "boolean",
      "default": true,
      "description": "Enable /start-act command for quick switching from plan to act mode"
    },
    "enable_plan_approval": {
      "type": "boolean",
      "default": true,
      "description": "Enable plan approval workflow. When enabled, plans must be approved using /approve-plan before execution."
    },
    "prompt_source": {
      "type": "string",
      "enum": ["local", "github", "auto"],
      "default": "local",
      "description": "Source for prompts: 'local' (use local files), 'github' (fetch from Cline repo), 'auto' (cache -> github -> local)"
    },
    "cline_version": {
      "type": "string",
      "default": "latest",
      "description": "Cline version to use: 'latest' or specific version/branch (e.g., 'main', 'v1.2.3')"
    },
    "cache_ttl": {
      "type": "number",
      "minimum": 1,
      "default": 24,
      "description": "Cache time-to-live in hours"
    },
    "fallback_to_local": {
      "type": "boolean",
      "default": true,
      "description": "Fallback to local prompts if GitHub fetch fails"
    }
  }
}
